import os
import re
from typing import Any, Dict, List, Optional

import requests


OPENAI_API_KEY = os.environ["OPENAI_API_KEY"]
OPENAI_MODEL = os.environ.get("OPENAI_MODEL", "omni-moderation-latest")
OPENAI_API_URL = "https://api.openai.com/v1/moderations"


def _call_openai_moderation(text: str) -> Dict[str, Any]:
    resp = requests.post(
        OPENAI_API_URL,
        headers={
            "Authorization": f"Bearer {OPENAI_API_KEY}",
            "Content-Type": "application/json",
        },
        json={
            "model": OPENAI_MODEL,
            "input": text,
        },
        timeout=30,
    )
    resp.raise_for_status()
    data = resp.json()
    results = data.get("results") or []
    if not results:
        raise ValueError("No moderation results returned from OpenAI.")
    return results[0]


def _category_thresholds() -> Dict[str, float]:
    return {
        "harassment": 0.5,
        "harassment/threatening": 0.4,
        "hate": 0.5,
        "hate/threatening": 0.4,
        "self-harm": 0.4,
        "self-harm/intent": 0.35,
        "self-harm/instructions": 0.3,
        "sexual": 0.6,
        "sexual/minors": 0.01,
        "violence": 0.5,
        "violence/graphic": 0.35,
        "illicit": 0.45,
        "illicit/violent": 0.35,
    }


def _extract_triggered_categories(result: Dict[str, Any]) -> List[str]:
    flagged = result.get("categories", {}) or {}
    scores = result.get("category_scores", {}) or {}
    thresholds = _category_thresholds()

    triggered: List[str] = []
    for category, is_flagged in flagged.items():
        score = float(scores.get(category, 0.0) or 0.0)
        threshold = thresholds.get(category, 0.5)
        if bool(is_flagged) or score >= threshold:
            triggered.append(category)
    return sorted(set(triggered))


def _span_patterns_for_categories(categories: List[str]) -> List[str]:
    patterns: List[str] = []

    if any(c.startswith("hate") for c in categories):
        patterns += [
            r"\b(?:slur|slurs)\b",
            r"\b(?:kill|exterminate|eliminate)\s+(?:all\s+)?(?:[A-Za-z][\w-]*)\b",
            r"\b(?:those|these)\s+(?:people|group|groups)\s+(?:are|should be)\s+(?:eradicated|removed|killed)\b",
        ]

    if any(c.startswith("harassment") for c in categories):
        patterns += [
            r"\b(?:idiot|moron|stupid|dumbass|loser|piece of shit)\b",
            r"\bgo\s+(?:die|kill yourself)\b",
            r"\byou(?:'re| are)\s+(?:worthless|pathetic|disgusting)\b",
        ]

    if any(c.startswith("self-harm") for c in categories):
        patterns += [
            r"\bkill\s+yourself\b",
            r"\bsuicide\b",
            r"\bself[- ]harm\b",
            r"\boverdose\b",
            r"\bhow\s+to\s+(?:hang|cut|poison)\s+yourself\b",
        ]

    if any(c.startswith("sexual/minors") for c in categories):
        patterns += [
            r"\b(?:child|minor|underage)\s+(?:sexual|sex|nude|explicit)\b",
            r"\b(?:sexual|sex)\s+(?:with|involving)\s+(?:a\s+)?(?:child|minor|underage)\b",
        ]
    elif any(c.startswith("sexual") for c in categories):
        patterns += [
            r"\b(?:rape|molest|incest)\b",
            r"\b(?:explicit|graphic)\s+sex(?:ual)?\b",
            r"\bnudes?\b",
        ]

    if any(c.startswith("violence") for c in categories):
        patterns += [
            r"\b(?:murder|kill|shoot|stab|behead|strangle|bomb)\b",
            r"\bhow\s+to\s+make\s+(?:a\s+)?bomb\b",
            r"\bgraphic\s+(?:gore|violence)\b",
        ]

    if any(c.startswith("illicit") for c in categories):
        patterns += [
            r"\bhow\s+to\s+(?:buy|sell|traffic|smuggle)\b",
            r"\b(?:meth|cocaine|heroin|fentanyl)\b",
            r"\b(?:credit card fraud|wire fraud|money laundering)\b",
        ]

    return patterns


def _find_unsafe_spans(text: str, categories: List[str]) -> List[Dict[str, Any]]:
    patterns = _span_patterns_for_categories(categories)
    spans: List[Dict[str, Any]] = []

    for pattern in patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            spans.append(
                {
                    "start": match.start(),
                    "end": match.end(),
                    "text": text[match.start():match.end()],
                    "reason": categories,
                }
            )

    spans.sort(key=lambda s: (s["start"], s["end"]))
    merged: List[Dict[str, Any]] = []
    for span in spans:
        if not merged or span["start"] > merged[-1]["end"]:
            merged.append(span)
        else:
            merged[-1]["end"] = max(merged[-1]["end"], span["end"])
            merged[-1]["text"] = text[merged[-1]["start"]:merged[-1]["end"]]
            merged[-1]["reason"] = sorted(set(merged[-1]["reason"]) | set(span["reason"]))

    return merged


def _redact_text(text: str, spans: List[Dict[str, Any]], replacement: str = "[REDACTED]") -> str:
    if not spans:
        return text

    out: List[str] = []
    cursor = 0
    for span in spans:
        out.append(text[cursor:span["start"]])
        out.append(replacement)
        cursor = span["end"]
    out.append(text[cursor:])
    return "".join(out)


def moderate_text(text: str, redact: bool = False) -> Dict[str, Any]:
    result = _call_openai_moderation(text)
    categories = _extract_triggered_categories(result)
    spans = _find_unsafe_spans(text, categories)

    output: Dict[str, Any] = {
        "provider": "openai",
        "model": OPENAI_MODEL,
        "flagged": bool(result.get("flagged", False) or categories),
        "categories": categories,
        "spans": spans,
    }

    if redact:
        output["redacted_text"] = _redact_text(text, spans)

    return output


def flag_unsafe_spans(text: str) -> Dict[str, Any]:
    return moderate_text(text, redact=False)


def redact_unsafe_spans(text: str) -> Dict[str, Any]:
    return moderate_text(text, redact=True)
